function getFriendlyAuthError(err) {
	const code = err?.code || "";
	if (code === "auth/operation-not-allowed") return "Email/Password sign-in is currently disabled in Firebase Console. Enable it in Firebase Authentication → Sign-in method, or use \"Continue with Google\" below.";
	if (code === "auth/email-already-in-use") return "This email is already registered. Please switch to Sign In.";
	if (code === "auth/wrong-password" || code === "auth/invalid-credential") return "Incorrect email or password. Try again or reset your password.";
	if (code === "auth/user-not-found") return "No account found with this email. Please create an account first.";
	if (code === "auth/weak-password") return "Password must be at least 6 characters long.";
	if (code === "auth/popup-closed-by-user") return "Google sign-in popup was closed before completing.";
	if (code === "auth/popup-blocked" || code === "auth/operation-not-supported-in-this-environment") return "Google popup is blocked in this WebView/browser. Please use Email & Password sign-in/registration above (make sure Email/Password is enabled in Firebase Console).";
	return err?.message || "Authentication failed. Please try again.";
}
